"use client";

import { profile } from "@/lib/config";
import { useState, useEffect } from "react";

const LINKS = [
  { label: "About", href: "#about" },
  { label: "Experience", href: "#experience" },
  { label: "Work", href: "#work" },
  { label: "Stack", href: "#stack" },
  { label: "Contact", href: "#contact" },
];

export default function Nav() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <header className="fixed top-4 inset-x-0 z-50 flex justify-center px-4 transition-all duration-300">
      <div
        className={`w-full max-w-3xl rounded-full border border-white/10 bg-[#181818]/85 backdrop-blur-md px-4 sm:px-6 py-2.5 flex items-center justify-between transition-all duration-300 ${
          scrolled ? "shadow-2xl shadow-black/80 border-white/15 bg-[#141416]/95" : ""
        }`}
      >
        {/* Brand logo / monogram */}
        <a
          href="#hero"
          className="flex items-center gap-2 text-white hover:opacity-90 transition-opacity"
        >
          <div className="flex h-7 w-7 items-center justify-center rounded-full bg-white/10 border border-white/15 font-mono text-xs font-bold text-white">
            P
          </div>
          <span className="font-semibold text-sm tracking-tight hidden sm:inline-block text-white/90">
            Prathyush
          </span>
        </a>

        {/* Navigation Links */}
        <nav className="flex items-center gap-1 sm:gap-2">
          {LINKS.map((l) => (
            <a
              key={l.href}
              href={l.href}
              className="px-3 py-1.2 rounded-full text-xs font-medium text-zinc-400 hover:text-white hover:bg-white/5 transition-all"
            >
              {l.label}
            </a>
          ))}
        </nav>

        {/* Availability status badge */}
        <a
          href="#contact"
          className="hidden md:flex items-center gap-2 rounded-full border border-emerald-500/20 bg-emerald-500/10 px-3 py-1 text-xs font-medium text-emerald-400 hover:bg-emerald-500/20 transition-all"
        >
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500" />
          </span>
          <span>Available</span>
        </a>
      </div>
    </header>
  );
}

